DllDef rawspeed3_handle_t rawspeed3_init(const char* cameradefs, bool is_file)
{
    if(!cameradefs) return nullptr;
    try
    {
        auto *handle = new rawspeed3_handle_data(cameradefs, is_file);
        return (void*)handle;
